exercise.referenceSolution:
#include <stdio.h>

#define MAX 20000

static char text[MAX];
static char out[MAX];

int main(void) {
    int len = 0, c;
    while ((c = getchar()) != EOF && len < MAX - 1) {
        if (c == '\n' && len > 0 && text[len - 1] == '\\') {
            len--;                       // склейка: убрать \ и перевод строки
            continue;
        }
        text[len++] = (char)c;
    }
    int n = 0;
    int i = 0;
    while (i < len) {
        char ch = text[i];
        if (ch == '"' || ch == '\'') {
            out[n++] = text[i++];
            while (i < len && text[i] != ch && text[i] != '\n') {
                if (text[i] == '\\' && i + 1 < len) {
                    out[n++] = text[i++];
                }
                out[n++] = text[i++];
            }
            if (i < len && text[i] == ch) {
                out[n++] = text[i++];
            }
        } else if (ch == '/' && i + 1 < len && text[i + 1] == '*') {
            int j = i + 2;
            while (j + 1 < len && !(text[j] == '*' && text[j + 1] == '/')) {
                j++;
            }
            if (j + 1 >= len) {
                printf("ошибка: незакрытый комментарий\n");
                return 0;
            }
            out[n++] = ' ';
            i = j + 2;
        } else if (ch == '/' && i + 1 < len && text[i + 1] == '/') {
            while (i < len && text[i] != '\n') {
                i++;
            }
            out[n++] = ' ';
        } else {
            out[n++] = text[i++];
        }
    }
    fwrite(out, 1, (size_t)n, stdout);
    return 0;
}

