#include <ctype.h>
#include <stdio.h>
#include <string.h>

static int is_ident(char c) {
    return isalnum((unsigned char)c) || c == '_';
}

int main(void) {
    char file[128];
    char line[256];
    if (scanf("%127s", file) != 1) {
        return 0;
    }
    getchar();                                   // перевод строки после имени
    int number = 0;
    while (fgets(line, sizeof line, stdin) != NULL) {
        number++;
        const char *p = line;
        while (*p == ' ' || *p == '\t') {
            p++;
        }
        if (*p == '#') {
            const char *q = p + 1;
            while (*q == ' ' || *q == '\t') {
                q++;
            }
            if (strncmp(q, "line", 4) == 0 && !is_ident(q[4])) {
                int next;
                char name[100];
                int got = sscanf(q + 4, "%d \"%99[^\"]\"", &next, name);
                if (got >= 1) {
                    number = next - 1;
                }
                if (got == 2) {
                    strcpy(file, name);
                }
                continue;
            }
            fputs(line, stdout);
            continue;
        }
        for (size_t i = 0; line[i] != '\0';) {
            if (line[i] == '"') {
                putchar(line[i++]);
                while (line[i] != '\0' && line[i] != '"') {
                    if (line[i] == '\\' && line[i + 1] != '\0') {
                        putchar(line[i++]);
                    }
                    putchar(line[i++]);
                }
                if (line[i] == '"') {
                    putchar(line[i++]);
                }
            } else if (line[i] == '/' && line[i + 1] == '/') {
                fputs(line + i, stdout);
                break;
            } else if (is_ident(line[i])) {
                size_t start = i;
                while (is_ident(line[i])) {
                    i++;
                }
                size_t len = i - start;
                if (len == 8 && strncmp(line + start, "__LINE__", 8) == 0) {
                    printf("%d", number);
                } else if (len == 8 && strncmp(line + start, "__FILE__", 8) == 0) {
                    printf("\"%s\"", file);
                } else {
                    fwrite(line + start, 1, len, stdout);
                }
            } else {
                putchar(line[i++]);
            }
        }
    }
    return 0;
}

additionalExercises.description:
Разбейте текст программы на токены так, как это делает препроцессор. Текст подаётся до конца ввода; комментариев и директив в нём нет. Пробелы, табуляции и переводы строк разделяют токены и сами токенами не являются.

Токены и их типы:
- `идентификатор` — латинская буква или `_`, затем буквы, цифры и `_`;
- `число` — начинается с цифры или с точки, за которой цифра; продолжается буквами, цифрами, `_`, точками, а также знаками `+` и `-`, если перед ними стоит `e`, `E`, `p` или `P` (так `1e-5`, `0x1F`, `3.14f` и `10u` — по одному числу);
- `строка` — `"…"`, `символ` — `'…'`; внутри возможны экранирования вида `\"`, `\'`, `\\`;
- `знак` — знаки операций и пунктуации. Выбирается **самый длинный** подходящий: трёхсимвольные `<<=` `>>=` `...`; двухсимвольные `++` `--` `->` `<<` `>>` `<=` `>=` `==` `!=` `&&` `||` `+=` `-=` `*=` `/=` `%=` `&=` `|=` `^=` `##`; односимвольные `+ - * / % = < > ! & | ^ ~ ? : ; , . ( ) [ ] { } #`;
- любой другой символ — `неизвестно`.

Для каждого токена напечатайте строку `тип: токен`.

