#include <ctype.h>
#include <stdio.h>
#include <string.h>

static const char *const punctuators[] = {
    "<<=", ">>=", "...",
    "++", "--", "->", "<<", ">>", "<=", ">=", "==", "!=", "&&", "||",
    "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "##",
    "+", "-", "*", "/", "%", "=", "<", ">", "!", "&", "|", "^", "~",
    "?", ":", ";", ",", ".", "(", ")", "[", "]", "{", "}", "#",
};

static void print_token(const char *type, const char *text, size_t len) {
    printf("%s: %.*s\n", type, (int)len, text);
}

int main(void) {
    static char text[6000];
    size_t len = fread(text, 1, sizeof text - 1, stdin);
    text[len] = '\0';
    size_t i = 0;
    while (i < len) {
        unsigned char c = (unsigned char)text[i];
        if (isspace(c)) {
            i++;
            continue;
        }
        size_t start = i;
        if (isalpha(c) || c == '_') {
            while (isalnum((unsigned char)text[i]) || text[i] == '_') {
                i++;
            }
            print_token("идентификатор", text + start, i - start);
        } else if (isdigit(c) || (c == '.' && isdigit((unsigned char)text[i + 1]))) {
            i++;
            for (;;) {
                char d = text[i];
                if ((d == '+' || d == '-') && strchr("eEpP", text[i - 1]) != NULL) {
                    i++;
                } else if (isalnum((unsigned char)d) || d == '_' || d == '.') {
                    i++;
                } else {
                    break;
                }
            }
            print_token("число", text + start, i - start);
        } else if (c == '"' || c == '\'') {
            i++;
            while (i < len && text[i] != (char)c && text[i] != '\n') {
                if (text[i] == '\\' && i + 1 < len) {
                    i++;
                }
                i++;
            }
            if (i < len && text[i] == (char)c) {
                i++;
            }
            print_token(c == '"' ? "строка" : "символ", text + start, i - start);
        } else {
            size_t best = 0;
            for (size_t k = 0; k < sizeof punctuators / sizeof punctuators[0] && best == 0; k++) {
                size_t plen = strlen(punctuators[k]);
                if (strncmp(text + i, punctuators[k], plen) == 0) {
                    best = plen;
                }
            }
            if (best == 0) {
                print_token("неизвестно", text + i, 1);
                i++;
            } else {
                print_token("знак", text + i, best);
                i += best;
            }
        }
    }
    return 0;
}

